    function escapeJSON(string memory input) internal pure returns (string memory) {
        bytes memory buffer = bytes(input);
        bytes memory output = new bytes(2 * buffer.length); // worst case scenario
        uint256 outputLength = 0;

        for (uint256 i; i < buffer.length; ++i) {
            bytes1 char = bytes1(_unsafeReadBytesOffset(buffer, i));
            if (((SPECIAL_CHARS_LOOKUP & (1 << uint8(char))) != 0)) {
                output[outputLength++] = "\\";
                if (char == 0x08) output[outputLength++] = "b";
                else if (char == 0x09) output[outputLength++] = "t";
                else if (char == 0x0a) output[outputLength++] = "n";
                else if (char == 0x0c) output[outputLength++] = "f";
                else if (char == 0x0d) output[outputLength++] = "r";
                else if (char == 0x5c) output[outputLength++] = "\\";
                else if (char == 0x22) {
                    // solhint-disable-next-line quotes
                    output[outputLength++] = '"';
                }
            } else {
                output[outputLength++] = char;
            }
        }
        // write the actual length and deallocate unused memory
        assembly ("memory-safe") {
            mstore(output, outputLength)
            mstore(0x40, add(output, shl(5, shr(5, add(outputLength, 63)))))
        }

        return string(output);
    }

    /**
     * @dev Reads a bytes32 from a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }
}

contracts/AgentIdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title AgentIdentityRegistry
 * @notice ERC-8004 Agent Identity system - issues NFT passports to AI agent operators
 * @dev One passport per operator address. Admin can verify or revoke agents.
 */
contract AgentIdentityRegistry is ERC721URIStorage, Ownable {

    // ============ State Variables ============

    uint256 private _nextTokenId;

    // operator address => tokenId (0 means no passport)
    mapping(address => uint256) private _operatorPassport;

    // tokenId => verified status
    mapping(uint256 => bool) private _verified;

    // tokenId => revoked status
    mapping(uint256 => bool) private _revoked;

    // ============ Events ============

    event AgentRegistered(uint256 indexed tokenId, address indexed operator, string metadataURI);
    event MetadataUpdated(uint256 indexed tokenId, string metadataURI);
    event AgentVerified(uint256 indexed tokenId);
    event AgentRevoked(uint256 indexed tokenId);

    // ============ Errors ============

    error AlreadyRegistered();
    error NotTokenOwner();
    error AlreadyVerified();
    error AlreadyRevoked();
    error NotRegistered();

    // ============ Constructor ============

    constructor() ERC721("Agent Identity Passport", "AID") Ownable(msg.sender) {
        // tokenId 0 is reserved as the "no passport" sentinel value
        _nextTokenId = 1;
    }

    // ============ Core Functions ============

    /**
     * @notice Register a new agent and mint an NFT passport
     * @param metadataURI The metadata URI for the agent passport
     * @return tokenId The newly minted token ID
     */
    function registerAgent(string calldata metadataURI) external returns (uint256) {
        if (_operatorPassport[msg.sender] != 0) revert AlreadyRegistered();

        uint256 tokenId = _nextTokenId;
        _nextTokenId++;

        _mint(msg.sender, tokenId);
        _setTokenURI(tokenId, metadataURI);

        _operatorPassport[msg.sender] = tokenId;

        emit AgentRegistered(tokenId, msg.sender, metadataURI);

        return tokenId;
    }

    /**
     * @notice Update the metadata URI for an agent passport
     * @param tokenId The token ID to update
     * @param metadataURI The new metadata URI
     */
    function updateMetadata(uint256 tokenId, string calldata metadataURI) external {
        if (ownerOf(tokenId) != msg.sender) revert NotTokenOwner();

        _setTokenURI(tokenId, metadataURI);

        emit MetadataUpdated(tokenId, metadataURI);
    }

    // ============ Admin Functions ============

    /**
     * @notice Verify an agent (admin only)
     * @param tokenId The token ID to verify
     */
    function verifyAgent(uint256 tokenId) external onlyOwner {
        if (_ownerOf(tokenId) == address(0)) revert NotRegistered();
        if (_verified[tokenId]) revert AlreadyVerified();

        _verified[tokenId] = true;

        emit AgentVerified(tokenId);
    }

    /**
     * @notice Revoke an agent (admin only)
     * @param tokenId The token ID to revoke
     */
    function revokeAgent(uint256 tokenId) external onlyOwner {
        if (_ownerOf(tokenId) == address(0)) revert NotRegistered();
        if (_revoked[tokenId]) revert AlreadyRevoked();

        _revoked[tokenId] = true;

        emit AgentRevoked(tokenId);
    }

    // ============ View Functions ============

    /**
     * @notice Get the passport token ID for an operator address
     * @param operator The operator address
     * @return tokenId The token ID (0 if none)
     */
    function getPassportId(address operator) external view returns (uint256) {
        return _operatorPassport[operator];
    }

    /**
     * @notice Check if an agent is verified
     * @param tokenId The token ID to check
     * @return Whether the agent is verified
     */
    function isAgentVerified(uint256 tokenId) external view returns (bool) {
        return _verified[tokenId];
    }

    /**
     * @notice Check if an agent is revoked
     * @param tokenId The token ID to check
     * @return Whether the agent is revoked
     */
    function isAgentRevoked(uint256 tokenId) external view returns (bool) {
        return _revoked[tokenId];
    }
}

contracts/AgentReputationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

interface IAgentIdentityRegistry {
    function getPassportId(address operator) external view returns (uint256);
    function isAgentRevoked(uint256 tokenId) external view returns (bool);
}

/**
 * @title AgentReputationRegistry
 * @notice Tracks reputation signals and transaction history for registered AI agents
 * @dev References AgentIdentityRegistry for identity validation
 */
contract AgentReputationRegistry is Ownable {

    // ============ Structs ============

    struct Reputation {
        uint256 positiveSignals;
        uint256 negativeSignals;
        uint256 txCount;
        uint256 totalVolume;
        uint256 trustScore;
    }

    // ============ State Variables ============

    IAgentIdentityRegistry public identityRegistry;

    // tokenId => reputation data
    mapping(uint256 => uint256) public positiveSignals;
    mapping(uint256 => uint256) public negativeSignals;
    mapping(uint256 => uint256) public txCount;
    mapping(uint256 => uint256) public totalVolume;

    // authorized reporters
    mapping(address => bool) public authorizedReporters;

    // ============ Events ============

    event SignalPosted(uint256 indexed tokenId, bool positive, string reason, address indexed reporter);
    event TransactionRecorded(uint256 indexed tokenId, uint256 amountUSDC6Dec, address indexed reporter);
    event ReporterAdded(address indexed reporter);
    event ReporterRemoved(address indexed reporter);

    // ============ Errors ============

    error UnauthorizedReporter();
    error InvalidTokenId();

    // ============ Constructor ============

    constructor(address _identityRegistry) Ownable(msg.sender) {
        identityRegistry = IAgentIdentityRegistry(_identityRegistry);
    }

    // ============ Modifiers ============

    modifier onlyReporter() {
        if (!authorizedReporters[msg.sender]) revert UnauthorizedReporter();
        _;
    }

    modifier validToken(uint256 tokenId) {
        if (tokenId == 0) revert InvalidTokenId();
        _;
    }

    // ============ Core Functions ============

    /**
     * @notice Post a trust signal for an agent
     * @param tokenId The agent passport token ID
     * @param positive Whether the signal is positive
     * @param reason Description of the signal
     */
    function postSignal(
        uint256 tokenId,
        bool positive,
        string calldata reason
    ) external onlyReporter validToken(tokenId) {
        if (positive) {
            positiveSignals[tokenId]++;
        } else {
            negativeSignals[tokenId]++;
        }

        emit SignalPosted(tokenId, positive, reason, msg.sender);
    }

    /**
     * @notice Record a transaction for an agent
     * @param tokenId The agent passport token ID
     * @param amountUSDC6Dec The transaction amount in USDC (6 decimals)
     */
    function recordTransaction(
        uint256 tokenId,
        uint256 amountUSDC6Dec
    ) external onlyReporter validToken(tokenId) {
        txCount[tokenId]++;
        totalVolume[tokenId] += amountUSDC6Dec;

        emit TransactionRecorded(tokenId, amountUSDC6Dec, msg.sender);
    }

    // ============ Admin Functions ============

    /**
     * @notice Add an authorized reporter
     * @param reporter The address to authorize
     */
    function addReporter(address reporter) external onlyOwner {
        authorizedReporters[reporter] = true;
        emit ReporterAdded(reporter);
    }

    /**
     * @notice Remove an authorized reporter
     * @param reporter The address to deauthorize
     */
    function removeReporter(address reporter) external onlyOwner {
        authorizedReporters[reporter] = false;
        emit ReporterRemoved(reporter);
    }

    // ============ View Functions ============

    /**
     * @notice Calculate the trust score for an agent (0-100)
     * @param tokenId The agent passport token ID
     * @return score The trust score
     *
     * @dev Formula:
     *   - If signals exist: (positiveSignals * 100) / (positiveSignals + negativeSignals)
     *   - If no signals: base score of 50 + volume bonus
     *   - Volume bonus: min(txCount, 50) / 5, capped at 10
     */
    function getTrustScore(uint256 tokenId) public view returns (uint256) {
        uint256 pos = positiveSignals[tokenId];
        uint256 neg = negativeSignals[tokenId];

        if (pos + neg > 0) {
            return (pos * 100) / (pos + neg);
        }

        // Base score with volume bonus
        uint256 count = txCount[tokenId];
        uint256 cappedCount = count < 50 ? count : 50;
        uint256 volumeBonus = cappedCount / 5; // max 10
        return 50 + volumeBonus;
    }

    /**
     * @notice Get the full reputation data for an agent
     * @param tokenId The agent passport token ID
     * @return reputation The reputation struct
     */
    function getReputation(uint256 tokenId) external view returns (Reputation memory) {
        return Reputation({
            positiveSignals: positiveSignals[tokenId],
            negativeSignals: negativeSignals[tokenId],
            txCount: txCount[tokenId],
            totalVolume: totalVolume[tokenId],
            trustScore: getTrustScore(tokenId)
        });
    }
}

contracts/DepositRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DepositRouter
 * @notice Routes ERC20 (USDC/USDT) deposits + ETH gas funding in a single user transaction.
 * @dev User approves this contract for the specific token, then each deposit is a single tx:
 *      depositWithGas(token, holdingWallet, amount) with msg.value ETH.
 *      - Token is pulled from user to holdingWallet via safeTransferFrom
 *      - ETH is forwarded to collectionWallet for backend gas funding
 */
contract DepositRouter is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    address public collectionWallet;

    error ZeroAmount();
    error ZeroAddress();
    error EthTransferFailed();

    event DepositWithGas(
        address indexed user,
        address indexed holdingWallet,
        address indexed token,
        uint256 amount,
        uint256 ethAmount
    );
    event CollectionWalletUpdated(address indexed oldWallet, address indexed newWallet);

    constructor(address _collectionWallet) Ownable(msg.sender) {
        if (_collectionWallet == address(0)) revert ZeroAddress();
        collectionWallet = _collectionWallet;
    }

    /**
     * @notice Deposit ERC20 token to a holding wallet and forward ETH to collection wallet
     * @param token The ERC20 token address (USDC, USDT, etc.)
     * @param holdingWallet The holding wallet to receive the token
     * @param amount The token amount (6 decimals for USDC/USDT)
     */
    function depositWithGas(address token, address holdingWallet, uint256 amount) external payable nonReentrant {
        if (token == address(0) || holdingWallet == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();

        // Pull token from user to holding wallet
        IERC20(token).safeTransferFrom(msg.sender, holdingWallet, amount);

        // Forward ETH to collection wallet
        if (msg.value > 0) {
            (bool success, ) = collectionWallet.call{value: msg.value}("");
            if (!success) revert EthTransferFailed();
        }

        emit DepositWithGas(msg.sender, holdingWallet, token, amount, msg.value);
    }

    /**
     * @notice Update collection wallet address (owner only)
     */
    function setCollectionWallet(address _collectionWallet) external onlyOwner {
        if (_collectionWallet == address(0)) revert ZeroAddress();
        address old = collectionWallet;
        collectionWallet = _collectionWallet;
        emit CollectionWalletUpdated(old, _collectionWallet);
    }

    /**
     * @notice Recover accidentally sent ERC20 tokens (owner only)
     */
    function recoverERC20(address token, uint256 amount) external onlyOwner {
        IERC20(token).safeTransfer(msg.sender, amount);
    }

    /**
     * @notice Recover accidentally sent ETH (owner only)
     */
    function recoverETH() external onlyOwner {
        (bool success, ) = msg.sender.call{value: address(this).balance}("");
        if (!success) revert EthTransferFailed();
    }
}

contracts/Void402Facilitator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { FHE, euint128, inEuint128, ebool } from "@fhenixprotocol/contracts/FHE.sol";
import "./VoidFHERC20.sol";

/**
 * @title Void402Facilitator
 * @notice On-chain facilitator for x402 payments with FHE privacy
 * @dev Verifies and settles encrypted x402 payments without revealing amounts
 */
contract Void402Facilitator {
    // Reference to VoidFHERC20 token
    VoidFHERC20 public immutable token;

    // Payment request structure
    struct PaymentRequest {
        address payer;
        address payee;
        euint128 encryptedAmount; // Encrypted payment amount
        bytes32 paymentHash; // Hash of payment details for verification
        uint256 timestamp;
        bool settled;
    }

    // Mapping of payment requests
    mapping(bytes32 => PaymentRequest) public paymentRequests;

    // Events
    event PaymentRequested(
        bytes32 indexed paymentId,
        address indexed payer,
        address indexed payee,
        bytes32 encryptedAmountHash,
        uint256 timestamp
    );

    event PaymentSettled(
        bytes32 indexed paymentId,
        address indexed payer,
        address indexed payee,
        bytes32 encryptedAmountHash
    );

    event PaymentFailed(
        bytes32 indexed paymentId,
        string reason
    );

    constructor(address _tokenAddress) {
        token = VoidFHERC20(_tokenAddress);
    }

    /**
     * @notice Create a payment request for x402 payment
     * @param paymentId Unique identifier for the payment
     * @param payee Address receiving payment
     * @param encryptedAmount Encrypted payment amount (inEuint128)
     * @param paymentHash Hash of payment metadata (for verification)
     * @return success Whether payment request was created
     */
    function createPaymentRequest(
        bytes32 paymentId,
        address payee,
        inEuint128 calldata encryptedAmount,
        bytes32 paymentHash
    ) 
        public 
        returns (bool) 
    {
        require(
            paymentRequests[paymentId].timestamp == 0,
            "Payment ID already exists"
        );

        euint128 amount = FHE.asEuint128(encryptedAmount);

        paymentRequests[paymentId] = PaymentRequest({
            payer: msg.sender,
            payee: payee,
            encryptedAmount: amount,
            paymentHash: paymentHash,
            timestamp: block.timestamp,
            settled: false
        });

        bytes32 encryptedAmountHash = keccak256(encryptedAmount.data);
        emit PaymentRequested(
            paymentId,
            msg.sender,
            payee,
            encryptedAmountHash,
            block.timestamp
        );

        return true;
    }

    /**
     * @notice Settle an x402 payment (verify and transfer)
     * @param paymentId Payment identifier
     * @param encryptedAmount Encrypted amount to verify (inEuint128)
     * @param paymentHash Payment hash for verification
     * @return success Whether payment was settled
     * @return transferredAmount The actual amount transferred
     */
    function settlePayment(
        bytes32 paymentId,
        inEuint128 calldata encryptedAmount,
        bytes32 paymentHash
    )
        public
        returns (bool, euint128)
    {
        PaymentRequest storage request = paymentRequests[paymentId];
        
        require(request.timestamp != 0, "Payment request not found");
        require(!request.settled, "Payment already settled");
        require(request.paymentHash == paymentHash, "Invalid payment hash");

        // Verify encrypted amount matches using FHE comparison
        euint128 amount = FHE.asEuint128(encryptedAmount);
        ebool amountsMatch = FHE.eq(request.encryptedAmount, amount);
        require(
            FHE.decrypt(amountsMatch),
            "Encrypted amount mismatch"
        );

        // Transfer encrypted tokens from payer to payee
        euint128 transferredAmount = token.encryptedTransferFrom(
            request.payer,
            request.payee,
            encryptedAmount
        );

        // Check if transfer succeeded (transferred amount > 0)
        ebool transferSucceeded = FHE.gt(transferredAmount, FHE.asEuint128(0));
        if (!FHE.decrypt(transferSucceeded)) {
            emit PaymentFailed(paymentId, "Transfer failed");
            return (false, transferredAmount);
        }

        // Mark as settled
        request.settled = true;

        bytes32 encryptedAmountHash = keccak256(encryptedAmount.data);
        emit PaymentSettled(
            paymentId,
            request.payer,
            request.payee,
            encryptedAmountHash
        );

        return (true, transferredAmount);
    }

    /**
     * @notice Verify payment request exists and is valid
     * @param paymentId Payment identifier
     * @return exists Whether payment request exists
     * @return settled Whether payment is already settled
     * @return payee Address receiving payment
     */
    function verifyPaymentRequest(bytes32 paymentId)
        public
        view
        returns (
            bool exists,
            bool settled,
            address payee
        )
    {
        PaymentRequest storage request = paymentRequests[paymentId];
        exists = request.timestamp != 0;
        settled = request.settled;
        payee = request.payee;
    }

    /**
     * @notice Get payment request details (without revealing encrypted amount)
     * @param paymentId Payment identifier
     * @return payer Address making payment
     * @return payee Address receiving payment
     * @return timestamp When payment was requested
     * @return settled Whether payment is settled
     */
    function getPaymentRequest(bytes32 paymentId)
        public
        view
        returns (
            address payer,
            address payee,
            uint256 timestamp,
            bool settled
        )
    {
        PaymentRequest storage request = paymentRequests[paymentId];
        require(request.timestamp != 0, "Payment request not found");
        
        return (
            request.payer,
            request.payee,
            request.timestamp,
            request.settled
        );
    }
}

contracts/VoidFHERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { FHE, euint128, inEuint128, ebool } from "@fhenixprotocol/contracts/FHE.sol";
import { Permissioned, Permission } from "@fhenixprotocol/contracts/access/Permissioned.sol";

/**
 * @title VoidFHERC20
 * @notice Encrypted ERC20 token for confidential balances and transfers
 * @dev Uses FHE to encrypt balances and transaction amounts
 */
contract VoidFHERC20 is ERC20, Permissioned {
    // Mapping from address to encrypted balance
    mapping(address => euint128) private _encryptedBalances;
    
    // Mapping from address to encrypted allowance
    mapping(address => mapping(address => euint128)) private _encryptedAllowances;

    // Total supply (encrypted)
    euint128 private _encryptedTotalSupply;

    // Privacy level enum
    enum PrivacyLevel {
        Public,      // Fully visible
        Partial,     // Amount hidden, parties visible
        Full         // Amount + parties hidden
    }

    // User privacy preferences
    mapping(address => PrivacyLevel) public privacyLevels;

    event EncryptedTransfer(
        address indexed from,
        address indexed to,
        bytes32 encryptedAmount,
        PrivacyLevel privacyLevel
    );

    event PrivacyLevelUpdated(address indexed user, PrivacyLevel level);

    constructor(
        string memory name,
        string memory symbol,
        uint256 initialSupply
    ) ERC20(name, symbol) {
        // Mint initial supply using FHE
        euint128 encryptedInitial = FHE.asEuint128(initialSupply);
        _encryptedTotalSupply = encryptedInitial;
        _encryptedBalances[msg.sender] = encryptedInitial;
    }

    /**
     * @notice Get encrypted balance for a user (sealed output)
     * @param account Address to query
     * @param permission Permission struct with public key for sealing
     * @return Sealed encrypted balance as string
     */
    function getEncryptedBalance(
        address account,
        Permission calldata permission
    ) 
        public 
        view 
        onlyBetweenPermitted(permission, account, account)
        returns (string memory) 
    {
        return FHE.sealoutput(_encryptedBalances[account], permission.publicKey);
    }

    /**
     * @notice Transfer encrypted tokens (confidential)
     * @param to Recipient address
     * @param encryptedAmount Encrypted amount to transfer (inEuint128)
     * @return transferredAmount The actual amount transferred (may be less if insufficient balance)
     */
    function encryptedTransfer(
        address to,
        inEuint128 calldata encryptedAmount
    ) 
        public 
        returns (euint128) 
    {
        address from = msg.sender;
        euint128 amount = FHE.asEuint128(encryptedAmount);
        
        // Use FHE.select to conditionally transfer only if balance is sufficient
        // If balance >= amount, transfer amount; otherwise transfer 0
        euint128 amountToSend = FHE.select(
            FHE.gte(_encryptedBalances[from], amount),
            amount,
            FHE.asEuint128(0)
        );

        // Perform encrypted subtraction and addition using FHE operations
        _encryptedBalances[from] = _encryptedBalances[from] - amountToSend;
        _encryptedBalances[to] = _encryptedBalances[to] + amountToSend;

        // Emit encrypted transfer event (hash of encrypted amount for privacy)
        bytes32 encryptedAmountHash = keccak256(encryptedAmount.data);
        emit EncryptedTransfer(
            from,
            to,
            encryptedAmountHash,
            privacyLevels[from]
        );

        return amountToSend;
    }

    /**
     * @notice Set privacy level for user transactions
     * @param level Privacy level (Public, Partial, Full)
     */
    function setPrivacyLevel(PrivacyLevel level) public {
        privacyLevels[msg.sender] = level;
        emit PrivacyLevelUpdated(msg.sender, level);
    }

    /**
     * @notice Get privacy level for a user
     * @param account Address to query
     * @return Privacy level
     */
    function getPrivacyLevel(address account) 
        public 
        view 
        returns (PrivacyLevel) 
    {
        return privacyLevels[account];
    }

    /**
     * @notice Approve encrypted spending (for x402 facilitator)
     * @param spender Address to approve
     * @param encryptedAmount Encrypted amount to approve (inEuint128)
     * @return success Whether approval succeeded
     */
    function encryptedApprove(
        address spender, 
        inEuint128 calldata encryptedAmount
    ) 
        public 
        returns (bool) 
    {
        _encryptedAllowances[msg.sender][spender] = FHE.asEuint128(encryptedAmount);
        return true;
    }

    /**
     * @notice Get encrypted allowance (sealed output)
     * @param owner Token owner
     * @param spender Spender address
     * @param permission Permission struct with public key for sealing
     * @return Sealed encrypted allowance as string
     */
    function getEncryptedAllowance(
        address owner,
        address spender,
        Permission calldata permission
    )
        public
        view
        onlyBetweenPermitted(permission, owner, spender)
        returns (string memory)
    {
        return FHE.sealoutput(_encryptedAllowances[owner][spender], permission.publicKey);
    }

    /**
     * @notice Transfer from encrypted allowance (for facilitator)
     * @param from Sender address
     * @param to Recipient address
     * @param encryptedAmount Encrypted amount to transfer (inEuint128)
     * @return transferredAmount The actual amount transferred
     */
    function encryptedTransferFrom(
        address from,
        address to,
        inEuint128 calldata encryptedAmount
    )
        public
        returns (euint128)
    {
        euint128 amount = FHE.asEuint128(encryptedAmount);
        
        // Spend allowance: take minimum of allowance and requested amount
        euint128 spent = FHE.min(_encryptedAllowances[from][msg.sender], amount);
        _encryptedAllowances[from][msg.sender] = _encryptedAllowances[from][msg.sender] - spent;
        
        // Transfer: only transfer if balance is sufficient
        euint128 amountToSend = FHE.select(
            FHE.gte(_encryptedBalances[from], spent),
            spent,
            FHE.asEuint128(0)
        );

        // Perform FHE operations for balance updates
        _encryptedBalances[from] = _encryptedBalances[from] - amountToSend;
        _encryptedBalances[to] = _encryptedBalances[to] + amountToSend;

        // Emit event
        bytes32 encryptedAmountHash = keccak256(encryptedAmount.data);
        emit EncryptedTransfer(
            from,
            to,
            encryptedAmountHash,
            privacyLevels[from]
        );

        return amountToSend;
    }
}

contracts/X402PrivacyPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title X402PrivacyPool
 * @notice Privacy-preserving payment pool for x402 transactions on Base
 * @dev Equivalent to the Solana void402 program
 *
 * Features:
 * - Deposit USDC into privacy pool
 * - Withdraw with 1% fee
 * - Upload ZK proofs for private transfers
 * - Internal transfers (user to user, via relayer)
 * - External transfers (pool to any address, via relayer)
 */
contract X402PrivacyPool is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    // ============ Structs ============

    struct UserBalance {
        uint256 available;
        uint256 deposited;
        uint256 withdrawn;
        bool initialized;
    }

    struct Pool {
        uint256 totalDeposited;
        bool initialized;
    }

    struct Proof {
        address sender;
        uint256 nonce;
        uint256 amount;
        address token;
        bool used;
        bool initialized;
        bytes proofBytes;
        bytes commitmentBytes;
        bytes blindingFactorBytes;
    }

    // ============ State Variables ============

    // user => token => UserBalance
    mapping(address => mapping(address => UserBalance)) public userBalances;

    // token => Pool
    mapping(address => Pool) public pools;

    // proofId (keccak256(nonce)) => Proof
    mapping(bytes32 => Proof) public proofs;

    // Authorized relayers
    mapping(address => bool) public authorizedRelayers;

    // Fee settings (in basis points, 100 = 1%)
    uint256 public withdrawFee = 100; // 1%
    uint256 public poolMaintenanceFee = 50; // 0.5%

    // Fee recipient
    address public feeRecipient;

    // Supported tokens
    mapping(address => bool) public supportedTokens;

    // ============ Events ============

    event Deposit(address indexed user, address indexed token, uint256 amount);
    event Withdraw(address indexed user, address indexed token, uint256 amount, uint256 fee);
    event ProofUploaded(bytes32 indexed proofId, address indexed sender, uint256 amount);
    event InternalTransfer(bytes32 indexed proofId, address indexed recipient, uint256 amount);
    event ExternalTransfer(bytes32 indexed proofId, address indexed recipient, uint256 amount);
    event RelayerAdded(address indexed relayer);
    event RelayerRemoved(address indexed relayer);
    event TokenAdded(address indexed token);
    event TokenRemoved(address indexed token);

    // ============ Errors ============

    error InsufficientBalance();
    error ProofAlreadyUsed();
    error InvalidProof();
    error InvalidRelayerFee();
    error UnauthorizedRelayer();
    error UnsupportedToken();
    error ZeroAmount();
    error InvalidRecipient();

    // ============ Constructor ============

    constructor(address _feeRecipient) Ownable(msg.sender) {
        feeRecipient = _feeRecipient;
        authorizedRelayers[msg.sender] = true;
    }

    // ============ Modifiers ============

    modifier onlyRelayer() {
        if (!authorizedRelayers[msg.sender]) revert UnauthorizedRelayer();
        _;
    }

    modifier onlySupportedToken(address token) {
        if (!supportedTokens[token]) revert UnsupportedToken();
        _;
    }

    // ============ Admin Functions ============

    function addRelayer(address relayer) external onlyOwner {
        authorizedRelayers[relayer] = true;
        emit RelayerAdded(relayer);
    }

    function removeRelayer(address relayer) external onlyOwner {
        authorizedRelayers[relayer] = false;
        emit RelayerRemoved(relayer);
    }

    function addSupportedToken(address token) external onlyOwner {
        supportedTokens[token] = true;
        emit TokenAdded(token);
    }

    function removeSupportedToken(address token) external onlyOwner {
        supportedTokens[token] = false;
        emit TokenRemoved(token);
    }

    function setFeeRecipient(address _feeRecipient) external onlyOwner {
        feeRecipient = _feeRecipient;
    }

    function setWithdrawFee(uint256 _fee) external onlyOwner {
        require(_fee <= 500, "Fee too high"); // Max 5%
        withdrawFee = _fee;
    }

    function setPoolMaintenanceFee(uint256 _fee) external onlyOwner {
        require(_fee <= 200, "Fee too high"); // Max 2%
        poolMaintenanceFee = _fee;
    }

    // ============ Core Functions ============

    /**
     * @notice Deposit tokens into the privacy pool
     * @param token The ERC20 token to deposit
     * @param amount The amount to deposit
     */
    function deposit(
        address token,
        uint256 amount
    ) external nonReentrant onlySupportedToken(token) {
        if (amount == 0) revert ZeroAmount();

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        UserBalance storage userBalance = userBalances[msg.sender][token];
        userBalance.available += amount;
        userBalance.deposited += amount;
        userBalance.initialized = true;

        Pool storage pool = pools[token];
        pool.totalDeposited += amount;
        pool.initialized = true;

        emit Deposit(msg.sender, token, amount);
    }

    /**
     * @notice Withdraw tokens from the privacy pool (1% fee)
     * @param token The ERC20 token to withdraw
     * @param amount The amount to withdraw (before fee)
     */
    function withdraw(
        address token,
        uint256 amount
    ) external nonReentrant onlySupportedToken(token) {
        if (amount == 0) revert ZeroAmount();

        UserBalance storage userBalance = userBalances[msg.sender][token];
        if (userBalance.available < amount) revert InsufficientBalance();

        uint256 fee = (amount * withdrawFee) / 10000;
        uint256 withdrawAmount = amount - fee;

        userBalance.available -= amount;
        userBalance.withdrawn += amount;

        Pool storage pool = pools[token];
        pool.totalDeposited -= amount;

        IERC20(token).safeTransfer(msg.sender, withdrawAmount);

        if (fee > 0) {
            IERC20(token).safeTransfer(feeRecipient, fee);
        }

        emit Withdraw(msg.sender, token, withdrawAmount, fee);
    }

    /**
     * @notice Upload a zero-knowledge proof for a future transfer
     * @param nonce Unique nonce for this proof
     * @param amount The amount being proven
     * @param token The token for this proof
     * @param proofBytes The ZK proof data
     * @param commitmentBytes The commitment data
     * @param blindingFactorBytes The blinding factor
     */
    function uploadProof(
        uint256 nonce,
        uint256 amount,
        address token,
        bytes calldata proofBytes,
        bytes calldata commitmentBytes,
        bytes calldata blindingFactorBytes
    ) external nonReentrant onlySupportedToken(token) {
        if (amount == 0) revert ZeroAmount();

        UserBalance storage userBalance = userBalances[msg.sender][token];
        if (userBalance.available < amount) revert InsufficientBalance();

        bytes32 proofId = keccak256(abi.encodePacked(nonce));

        if (proofs[proofId].initialized) revert ProofAlreadyUsed();

        proofs[proofId] = Proof({
            sender: msg.sender,
            nonce: nonce,
            amount: amount,
            token: token,
            used: false,
            initialized: true,
            proofBytes: proofBytes,
            commitmentBytes: commitmentBytes,
            blindingFactorBytes: blindingFactorBytes
        });

        emit ProofUploaded(proofId, msg.sender, amount);
    }

    /**
     * @notice Initialize a recipient's balance (called by relayer before internal transfer)
     * @param recipient The recipient address
     * @param token The token to initialize for
     */
    function initRecipientBalance(
        address recipient,
        address token
    ) external onlyRelayer onlySupportedToken(token) {
        if (recipient == address(0)) revert InvalidRecipient();

        UserBalance storage recipientBalance = userBalances[recipient][token];
        if (!recipientBalance.initialized) {
            recipientBalance.initialized = true;
        }
    }

    /**
     * @notice Execute an internal transfer using a proof (relayer only)
     * @param proofId The ID of the proof to use
     * @param recipient The recipient address
     * @param relayerFee The fee for the relayer
     */
    function internalTransfer(
        bytes32 proofId,
        address recipient,
        uint256 relayerFee
    ) external nonReentrant onlyRelayer {
        if (recipient == address(0)) revert InvalidRecipient();

        Proof storage proof = proofs[proofId];

        if (!proof.initialized) revert InvalidProof();
        if (proof.used) revert ProofAlreadyUsed();
        if (proof.amount == 0) revert InvalidProof();
        if (relayerFee > proof.amount) revert InvalidRelayerFee();

        address token = proof.token;
        UserBalance storage senderBalance = userBalances[proof.sender][token];
        UserBalance storage recipientBalance = userBalances[recipient][token];

        if (senderBalance.available < proof.amount) revert InsufficientBalance();

        uint256 transferAmount = proof.amount - relayerFee;

        senderBalance.available -= proof.amount;
        recipientBalance.available += transferAmount;
        recipientBalance.initialized = true;

        proof.used = true;

        emit InternalTransfer(proofId, recipient, transferAmount);
    }

    /**
     * @notice Execute an external transfer using a proof (relayer only)
     * @param proofId The ID of the proof to use
     * @param recipient The external recipient address
     * @param relayerFee The fee for the relayer
     */
    function externalTransfer(
        bytes32 proofId,
        address recipient,
        uint256 relayerFee
    ) external nonReentrant onlyRelayer {
        if (recipient == address(0)) revert InvalidRecipient();

        Proof storage proof = proofs[proofId];

        if (!proof.initialized) revert InvalidProof();
        if (proof.used) revert ProofAlreadyUsed();
        if (proof.amount == 0) revert InvalidProof();

        address token = proof.token;
        UserBalance storage senderBalance = userBalances[proof.sender][token];
        Pool storage pool = pools[token];

        if (senderBalance.available < proof.amount) revert InsufficientBalance();

        uint256 poolFee = (proof.amount * poolMaintenanceFee) / 10000;
        uint256 minPoolFee = 500; // Minimum fee in smallest units
        if (poolFee < minPoolFee) poolFee = minPoolFee;

        uint256 totalFees = relayerFee + poolFee;
        if (totalFees > proof.amount) revert InvalidRelayerFee();
        uint256 transferAmount = proof.amount - totalFees;

        senderBalance.available -= proof.amount;
        pool.totalDeposited -= transferAmount;

        IERC20(token).safeTransfer(recipient, transferAmount);

        if (poolFee > 0) {
            IERC20(token).safeTransfer(feeRecipient, poolFee);
        }

        proof.used = true;

        emit ExternalTransfer(proofId, recipient, transferAmount);
    }

    // ============ View Functions ============

    function getUserBalance(
        address user,
        address token
    ) external view returns (uint256 available, uint256 deposited, uint256 withdrawn) {
        UserBalance storage balance = userBalances[user][token];
        return (balance.available, balance.deposited, balance.withdrawn);
    }

    function getPoolInfo(
        address token
    ) external view returns (uint256 totalDeposited, bool initialized) {
        Pool storage pool = pools[token];
        return (pool.totalDeposited, pool.initialized);
    }

    function getProofInfo(
        bytes32 proofId
    ) external view returns (
        address sender,
        uint256 amount,
        address token,
        bool used,
        bool initialized
    ) {
        Proof storage proof = proofs[proofId];
        return (proof.sender, proof.amount, proof.token, proof.used, proof.initialized);
    }

    function isRelayer(address account) external view returns (bool) {
        return authorizedRelayers[account];
    }

    function getProofId(uint256 nonce) external pure returns (bytes32) {
        return keccak256(abi.encodePacked(nonce));
    }
}

